const BUILD="2026-10-19.1955";
const TOWNS={"うるま市":{"pref":"沖縄県","cards":[{"tag":"へえ","hook":"城跡からローマ帝国のコイン","t":"勝連城跡では、3世紀から4世紀に作られたローマ帝国のコインが見つかりました。日本国内でローマの貨幣が見つかったのは初めてでした。","teaser":true},{"tag":"数字","hook":"本島で面積3位","t":"面積は約87.0km²で、本島26市町村中3位の広さ。人口は約122,371人（2021年）です。"},{"tag":"歴史","hook":"世界遺産で最も古いグスク","t":"勝連城跡は世界遺産に登録されたグスクの中で、最も築城年代が古いグスクです。"},{"tag":"歴史","hook":"勝連は沖縄の鎌倉","t":"民俗学者の柳田国男は、勝連が当時の文化の中心で、大和の鎌倉のようだとおもろさうしにある、と述べています。"},{"tag":"車窓","hook":"目線の高さに広がる海","t":"海中道路は大半が堤防の上を走る道で、目線とほぼ同じ高さで、両側にエメラルドグリーンの遠浅の海が広がります。"},{"tag":"歴史","hook":"石油会社が造った海の道","t":"海中道路は、平安座島に進出したアメリカの石油会社ガルフ社の負担で建設され、1972年に開通しました。"},{"tag":"ゆかり","hook":"島の名は「干潮」から？","t":"平安座島の名前は、干潮を意味する沖縄の言葉から来たとも、平家の落人が安徳天皇を祀った伝説にちなむともいわれます。"},{"tag":"味","hook":"別名はキャロットアイランド","t":"津堅島は島の3分の1がニンジン畑で、沖縄県内で作られるニンジンの2割がこの島で収穫されます。"},{"tag":"味","hook":"ウニと漬けたイカの塩辛","t":"浜比嘉島では6月から9月にウニ漁が最盛期を迎えます。ウニと一緒に漬けたイカの塩辛は島の特産品です。"},{"tag":"歴史","hook":"琉球の祖神を祀る洞窟","t":"浜比嘉島のアマミチュー洞窟は、琉球を開いた女神アマミキョと男神シルミキョを祀ったとされ、無病息災と子孫繁栄を願う拝所です。"},{"tag":"へえ","hook":"犬が見つけた泉","t":"伊計島のインナガーという泉は、崖下から濡れて登ってきた犬をたどった島民が見つけたと伝わっています。"},{"tag":"歴史","hook":"石垣の家が並ぶ古代の村","t":"伊計島の仲原遺跡は、石垣を壁にした竪穴の家が並ぶ集落の跡で、沖縄初の復元集落遺跡として整備されています。"},{"tag":"車窓","hook":"金武湾と中城湾に面する唯一の市","t":"うるま市は金武湾と中城湾の両方に面する唯一の自治体です。8つの島のうち5島へは、海中道路や橋で渡れます。"},{"tag":"クイズ","q":"市名「うるま」は古い沖縄の言葉で「サンゴの島」。では「ウル」の意味は？","a":"サンゴ（マは島）"}]},"与那原町":{"pref":"沖縄県","cards":[{"tag":"味","hook":"ご当地沖縄そばの元祖","t":"各地にある地名入りの沖縄そばの元祖が与那原そばです。戦前は駅の周りに店が並ぶ名物でしたが、当時の味を継ぐ店は残っていません。","teaser":true},{"tag":"数字","hook":"本島で小さい方の町","t":"面積は約5.2km²で、本島26市町村中26位。人口は約19,735人（2021年）です。"},{"tag":"へえ","hook":"首里城の赤瓦はこの町から","t":"窯業は与那原町を代表する工業で、町で作られた赤瓦は首里城の復元の際に使われています。"},{"tag":"へえ","hook":"盗む日時を予告する義賊","t":"運玉森を拠点にした義賊、運玉義留は、盗みに入る日時を前もって相手に告げたと民話に伝わっています。"},{"tag":"ゆかり","hook":"ベルリンで賞を取った映画","t":"運玉森に籠もった義賊の話をもとにした映画ウンタマギルーは、ベルリン国際映画祭のカリガリ賞などを受賞しました。"},{"tag":"歴史","hook":"沖縄県営鉄道のはじまり","t":"那覇と与那原を結んだ与那原線は、1914年に沖縄県営鉄道の最初の路線として開業しました。"},{"tag":"車窓","hook":"よみがえった軽便の駅舎","t":"与那原駅は、開業100周年を記念して2014年に昔の姿に復元されました。元の駅舎の9本の柱も残されています。"},{"tag":"ゆかり","hook":"皇太子を乗せたお召し列車","t":"1921年、ヨーロッパ歴訪から帰った皇太子裕仁、のちの昭和天皇のために、与那原駅から那覇駅までお召し列車が走りました。"},{"tag":"歴史","hook":"山原船が出入りした港町","t":"与那原は第二次世界大戦まで中城湾の天然の良港をもち、山原船も出入りする東海岸の交通の要衝でした。"},{"tag":"味","hook":"海岸3キロに育つ町の特産","t":"町の特産のひじきは、町の海岸線約3キロにわたって生息し、1年間に約50トンが収穫されます。"},{"tag":"へえ","hook":"ふるさと百選に選ばれた綱曳","t":"町の祭りのひとつ、与那原大綱曳は、2009年に沖縄、ふるさと百選の交流部門に認定されました。"},{"tag":"クイズ","q":"与那原という地名の「ヨナ」。もとは何を表す言葉？","a":"海岸のサンゴ砂です。「ハル」は開拓地という意味です。"}]},"中城村":{"pref":"沖縄県","cards":[{"tag":"へえ","hook":"ペリーも驚いた石垣","t":"1853年に訪れたペリー提督の一行は、中城城の城壁やアーチの門の技術の高さに驚き、詳しい報告を書きました。","teaser":true},{"tag":"数字","hook":"約15.5km²に約21,924人が暮らす町","t":"面積は約15.5km²、人口は約21,924人（2021年）。1km²あたり約1,418人です。"},{"tag":"車窓","hook":"東シナ海と太平洋を一望","t":"中城城の石垣の上に立つと、西に東シナ海、東に太平洋の中城湾、さらに洋上の島々まで見渡せます。"},{"tag":"歴史","hook":"最も遺構がよく残るグスク","t":"中城城は標高約160メートルの丘の上にあり、グスクの中で最も遺構がよく残っていることで知られています。"},{"tag":"歴史","hook":"護佐丸が仕上げた城","t":"1440年に護佐丸が三の郭と北の郭を増築し、中城城は今の形になりました。増築部分の城壁は相方積みという高度な技法です。"},{"tag":"へえ","hook":"薩摩の役人が隠れた城","t":"薩摩藩の支配下では、中国からの使節団が来ると、薩摩の役人は存在を知られないよう中城城に隠れていました。"},{"tag":"歴史","hook":"城の中に村役場があった","t":"中城城は王子の居城や番所を経て、1879年の廃藩置県の後は中城村役場として戦前まで使われました。"},{"tag":"車窓","hook":"ツワブキの名所でもある城","t":"中城城は、沖縄県の美ら島おきなわ・花と緑の名所100選に、ツワブキの名所として選ばれました。"},{"tag":"ゆかり","hook":"悪役の阿麻和利は英雄？","t":"正史では護佐丸が忠臣、阿麻和利が悪人とされますが、おもろさうしには阿麻和利を英雄として讃える歌が収められています。"},{"tag":"ゆかり","hook":"沖縄の言葉では「なかぐしく」","t":"中城村は「なかぐすくそん」と読み、沖縄の言葉では「なかぐしく」と呼ばれます。"},{"tag":"車窓","hook":"1929年まで陸の孤島","t":"村で最も標高が高い新垣は、県道35号線のもとになる道路が1929年に開通するまで、陸の孤島でした。"},{"tag":"歴史","hook":"引揚者が上陸した地","t":"村内の久場は戦後、本土や外地からの引揚者が沖縄本島へ帰る際の上陸地点となった地域です。"},{"tag":"へえ","hook":"琉球大学の学部は中城村に","t":"琉球大学の本部は西原町ですが、千原キャンパスの法文学部と理学部は中城村内にあり、周辺は学生アパートが並びます。"},{"tag":"クイズ","q":"1458年、中城城の護佐丸を攻めたのは、王府軍として来た誰？","a":"阿麻和利"}]},"今帰仁村":{"pref":"沖縄県","cards":[{"tag":"歴史","hook":"首里城と並ぶ世界遺産","t":"今帰仁城跡は2000年、首里城跡などとともに、琉球王国のグスク及び関連遺産群として世界遺産に登録されました。"},{"tag":"数字","hook":"約39.9km²に約9,275人が暮らす町","t":"面積は約39.9km²、人口は約9,275人（2021年）。1km²あたり約232人です。"},{"tag":"へえ","hook":"東西800mの巨大グスク","t":"今帰仁城跡は東西800メートル、南北350メートルにおよび、県内最大級のグスクとして知られています。"},{"tag":"車窓","hook":"城跡の石段を彩る桜","t":"今帰仁城跡の門から中心部へ向かう階段の両側にはカンヒザクラの並木があり、毎年1月末から2月初めに花を咲かせます。"},{"tag":"歴史","hook":"王国が滅んでも北の要","t":"北山王国は1416年、中山王の尚巴志に滅ぼされましたが、その後も今帰仁城には北山監守が置かれました。"},{"tag":"クイズ","q":"『おもろさうし』に出てくる、今帰仁の古い呼び名は？","a":"みやきせん"},{"tag":"歴史","hook":"鹿児島の島も北山の領土","t":"今帰仁を中心とした北山王国の領域には、鹿児島県に属する与論島と沖永良部島も含まれていたことが、確実視されています。"},{"tag":"へえ","hook":"山の名は「おんぶ」から？","t":"乙羽岳は、王子を背負って山中を逃げ回ったとされることから、背負うを意味する今帰仁の方言ウッパにちなみ、ウッパヤマと呼ばれるようになったと伝えられます。","teaser":true},{"tag":"車窓","hook":"山頂から与論島が見える","t":"乙羽岳の展望台からは古宇利島や羽地内海を見下ろし、北は伊平屋島や伊是名島、鹿児島県の与論島まで見渡せます。"},{"tag":"ゆかり","hook":"古宇利島の別名は「恋島」","t":"古宇利島は今帰仁村で恋島、くいじまとも呼ばれます。島を望む乙羽岳の展望台は、2012年に恋人の聖地に認定されました。"},{"tag":"車窓","hook":"海の上をまっすぐ2キロ","t":"古宇利大橋は、海の上をひたすらまっすぐ約2キロ走る橋です。両側に沖縄のマリンブルーの海が広がります。"},{"tag":"へえ","hook":"男柱と女柱の伝説","t":"古宇利大橋には、古宇利島に伝わる人類発祥の伝説にちなみ、男女を表す男柱と女柱があります。"},{"tag":"歴史","hook":"今帰仁城と築城勝負した城","t":"古宇利島の古宇利グスクには、対岸の今帰仁城と築城の勝負をして負け、廃城になったという言い伝えが残っています。"},{"tag":"歴史","hook":"源為朝がたどり着いた港？","t":"運天港には、源為朝がたどり着いた地だという伝説があり、港には上陸の碑が建っています。"}]},"八重瀬町":{"pref":"沖縄県","cards":[{"tag":"へえ","hook":"火事を防ぐため山をにらむ獅子","t":"富盛のシーサーは、村に火災が多かったため風水師に相談し、火山と呼ばれた八重瀬岳に向けて火除けに作られました。","teaser":true},{"tag":"数字","hook":"約27.0km²に約30,974人が暮らす町","t":"面積は約27.0km²、人口は約30,974人（2021年）。1km²あたり約1,149人です。"},{"tag":"歴史","hook":"最古で最大の村獅子","t":"富盛のシーサーは1689年の設置と記録され、高さ約142センチ。村獅子として最古で最大の石獅子です。"},{"tag":"歴史","hook":"2万年前の人骨が眠っていた","t":"1970年、港川人と呼ばれる4体の全身骨格が見つかりました。約2万年前から2万2千年前のものとされています。"},{"tag":"へえ","hook":"顔立ちはオーストラリア先住民似","t":"2009年の分析では、港川人の顔立ちは、現在の人類ではオーストラリア先住民やニューギニアの集団に近いとされました。"},{"tag":"ゆかり","hook":"太古の人の骨格に会える資料館","t":"八重瀬町立具志頭歴史民俗資料館には港川人コーナーがあり、全身骨格のレプリカや研究成果が紹介されています。"},{"tag":"へえ","hook":"町の名前は山から","t":"東風平町と具志頭村が合併するときに町名が公募され、応募総数662点の中から、八重瀬岳にちなんだ八重瀬町に決まりました。"},{"tag":"歴史","hook":"米軍がビッグアップルと呼んだ山","t":"町の最高峰、八重瀬岳は沖縄戦で日本軍最後の防衛線が置かれた場所で、アメリカ軍はこの山をビッグアップルと呼びました。"},{"tag":"車窓","hook":"北部より遅れて咲く南部の桜","t":"八重瀬岳北側の崖下にある公園には約900本のカンヒザクラが植えられ、本島北部より1週間から2週間遅れて咲きます。"},{"tag":"歴史","hook":"東シナ海を見渡す物見台跡","t":"八重瀬岳の北側の中腹には八重瀬グスクがあり、岩山の物見台跡からは東シナ海を遠くまで望めます。"},{"tag":"クイズ","q":"具志頭の読み方は1954年に「ぐしかみ」に変わりました。それまでは何と読んだ？","a":"ぐしちゃんです。"},{"tag":"へえ","hook":"十五夜の唐人行列と大和人行列","t":"十五夜のころには地域ごとに行事があり、富盛では唐人行列と大和人行列が行われます。"},{"tag":"へえ","hook":"町内の電話は4桁で通じた","t":"この地域では長らく市内局番がなく、町域内の電話は加入者番号の4桁をダイヤルするだけで通じました。"}]},"北中城村":{"pref":"沖縄県","cards":[{"tag":"歴史","hook":"返還の日に重要文化財へ","t":"中村家住宅は沖縄戦の戦禍を免れた民家です。沖縄が日本に返還された1972年5月15日、沖縄本島の民家で初めて国の重要文化財になりました。"},{"tag":"数字","hook":"本島で小さい方の町","t":"面積は約11.5km²で、本島26市町村中24位。人口は約17,038人（2021年）です。"},{"tag":"へえ","hook":"豚小屋がトイレを兼ねていた","t":"中村家住宅のフールは、アーチ型の石囲いの豚小屋です。人のトイレも兼ねていて、豚に排泄物を食べさせていました。"},{"tag":"歴史","hook":"農民は瓦を使えなかった","t":"琉球王国の時代、瓦は士族以上にしか認められず、農民の中村家が瓦を使えたのは明治の中頃からでした。それまでは竹瓦でした。"},{"tag":"へえ","hook":"日本で最も人口密度が高い村","t":"北中城村は、日本で最も人口密度が高い村とされています。村としての人口も、全国で5番目に多いとされています。","teaser":true},{"tag":"クイズ","q":"北中城村の面積は、東京都のどの区とほぼ同じ？","a":"千代田区"},{"tag":"歴史","hook":"中城村から分かれて誕生","t":"戦後、中城村は米軍施設によって南北に分断されました。1946年、北部の12の行政区が分かれて北中城村が生まれました。"},{"tag":"クイズ","q":"地名「ライカム」は、何の略？","a":"琉球米軍司令部（Ryukyu Command headquarters）"},{"tag":"へえ","hook":"モールの中に大型水槽","t":"イオンモール沖縄ライカムの吹き抜けには、水量100トンを超える大型水槽があり、トラフザメやナポレオンフィッシュも泳ぎます。"},{"tag":"車窓","hook":"沖縄で唯一のスマートIC","t":"喜舎場スマートインターチェンジは、ETC車専用で那覇方面の上りだけ。6時から22時まで、普通車と軽自動車が使えます。沖縄県で唯一とされています。"}]},"北谷町":{"pref":"沖縄県","cards":[{"tag":"歴史","hook":"基地の中に眠っていた大グスク","t":"北谷城は、首里城跡や今帰仁城跡などに次ぐ大きさとみられるグスクです。戦後75年間基地の中にあったため、調査はほとんど進んでいませんでした。","teaser":true},{"tag":"数字","hook":"本島で小さい方の町","t":"面積は約13.9km²で、本島26市町村中23位。人口は約28,167人（2021年）です。"},{"tag":"へえ","hook":"按司たちはお茶会好き？","t":"北谷城からは天目茶碗が数多く出土しています。城の按司たちが、お茶会をよく開いていたのではないかと考えられています。"},{"tag":"歴史","hook":"城主が次々替わった伝説","t":"北谷城は古くは金満按司の城で、金満按司は大川按司に、大川按司は谷茶大主に滅ぼされたと伝わっています。"},{"tag":"へえ","hook":"町名のルーツは「きたたん」","t":"北谷の名は、古い地名のきたたんと、琉球の行政区画を表すまきりに由来します。北谷という漢字は1609年以降に当てられました。"},{"tag":"クイズ","q":"「北谷」と書いて、何と読む？","a":"ちゃたん"},{"tag":"へえ","hook":"「ハンビー」は飛行場の名残","t":"北前や北谷の一帯は、ハンビーとも呼ばれます。もともと米軍のハンビー飛行場があったことに由来する呼び名です。"},{"tag":"車窓","hook":"海を埋め立てたアメリカの街","t":"美浜アメリカンビレッジは埋め立て地に造られ、アメリカの雰囲気を前面に押し出した街です。2003年には延べ830万人が訪れました。"},{"tag":"車窓","hook":"海沿いの遊歩道を走るカート","t":"美浜では2021年から、アメリカンビレッジとフィッシャリーナを結ぶ海沿いのボードウォークで、シャトルカートの運行が始まりました。"},{"tag":"味","hook":"キャンプ限定の「竜ちゃん食堂」","t":"中日ドラゴンズの春季キャンプの時期には、地元の飲食業組合が協力する竜ちゃん食堂が開かれ、沖縄そばなどが出されます。"},{"tag":"へえ","hook":"海から生まれた「宮城」と「港」","t":"北谷町の字、宮城は1971年、港は1977年に、どちらも埋め立てによって新しくできました。"},{"tag":"歴史","hook":"険しい土地を切り開いた謝苅","t":"戦後、平らな土地への移住は許されず、人々は険しい土地を切り開いて住み着きました。こうして謝苅の家々が密集する地区ができました。"},{"tag":"歴史","hook":"嘉手納はもと北谷の一部","t":"お隣の嘉手納町は、1948年まで北谷村の一部でした。それまでは北谷が読谷村と隣り合っていました。"},{"tag":"へえ","hook":"町立小学校の敷地は隣の市","t":"北谷町立北谷小学校の敷地は、町と市の境に面した沖縄市の側にあります。"}]},"南城市":{"pref":"沖縄県","cards":[{"tag":"へえ","hook":"国王も装いを改めた聖地","t":"斎場御嶽ではかつて、国王でさえ入口の御門口より先へ進むには、着物の合わせを女性の装いに改める必要があったといいます。","teaser":true},{"tag":"数字","hook":"約49.9km²に約44,318人が暮らす町","t":"面積は約49.9km²、人口は約44,318人（2021年）。1km²あたり約887人です。"},{"tag":"歴史","hook":"五穀の種が流れ着いた浜","t":"久高島の伊敷浜には、五穀の種が入った壺が流れ着いたと伝わり、島は五穀発祥の地とされています。"},{"tag":"へえ","hook":"島の土地は個人のものではない","t":"久高島では土地を字の名義で共有し、島を出るときは字へ返します。琉球王朝時代の地割制度が唯一残る島です。"},{"tag":"クイズ","q":"久高島の30歳から41歳の女性が、ナンチュという地位になるための儀礼イザイホー。何年に一度、行われてきた？","a":"12年に一度、午年に行われてきました。"},{"tag":"味","hook":"ウミヘビを燻製にした汁","t":"久高島では、イラブーと呼ばれるエラブウミヘビを燻製にして煮込んだイラブー汁が、島の名物です。"},{"tag":"へえ","hook":"鍾乳洞の中にエスカレーター","t":"鍾乳洞の玉泉洞には、1987年、世界初となる洞内エスカレーターが設置されました。"},{"tag":"車窓","hook":"男川と女川に分かれる湧き水","t":"垣花樋川では、集落の崖の中腹から湧く水が、男川と女川と呼ばれる二つの水路に分かれて流れ出ています。"},{"tag":"歴史","hook":"共同風呂まである石造りの井戸","t":"国の重要文化財の仲村渠樋川は、1912年から翌年にかけて造られた石造りの井泉です。男性用と女性用の水場や共同風呂が当初の形に復元されています。"},{"tag":"へえ","hook":"2万3000年前の釣り針","t":"南城市では2012年、約2万3000年前の旧石器時代の貝で作った釣り針が見つかりました。世界最古級です。"},{"tag":"ゆかり","hook":"三山を統一した王のふるさと","t":"佐敷は尚巴志が生まれた地です。尚巴志が三山を統一し、琉球王国の第一尚氏王統が始まりました。"},{"tag":"歴史","hook":"一枚岩をくり抜いた城門","t":"玉城城跡は主郭の城壁がほぼ完全に近い形で残り、自然の一枚岩をくり抜いて造られた城門があります。"},{"tag":"味","hook":"天ぷらの売店がある島","t":"太平洋に面した奥武島は漁業が盛んで、海産物の食堂や天ぷらの売店があります。"},{"tag":"ゆかり","hook":"あのアニメの舞台","t":"P.A.WORKS制作のアニメ、白い砂のアクアトープは、南城市が舞台になっています。"}]},"南風原町":{"pref":"沖縄県","cards":[{"tag":"へえ","hook":"沖縄でただ一つ、海のない町","t":"沖縄県の自治体で唯一、海に面していない町です。主要四島以外の島々の自治体まで広げても、内陸はここだけです。","teaser":true},{"tag":"数字","hook":"本島で小さい方の町","t":"面積は約10.8km²で、本島26市町村中25位。人口は約40,541人（2021年）です。"},{"tag":"へえ","hook":"沖縄の言葉では「ふぇーばる」","t":"南風原町は、ふつうはえばると読みますが、沖縄の言葉ではふぇーばると呼ばれます。"},{"tag":"歴史","hook":"首里王府の直轄地だった","t":"南風原は三山分立時代には中山に属し、1611年の慶長検地より前から、首里王府の直轄地域でした。"},{"tag":"へえ","hook":"空を飛んだと伝わる琉球の男","t":"飛び安里と呼ばれる安里周祥は、1780年頃に高津嘉山などから150から200メートル飛行したとの伝承があります。"},{"tag":"歴史","hook":"文字が浮かび上がる仕掛け花火","t":"安里周祥は1801年、冊封使をもてなす仕掛け花火を披露しました。松竹梅の文字が浮き出る花火だったと伝わります。"},{"tag":"ゆかり","hook":"町おこしで復元機が空へ","t":"1999年、南風原町の町おこしグループが飛び安里の復元機を作り、有人飛行に成功しました。"},{"tag":"クイズ","q":"「飛び安里」は、ある家の三代目だという説があります。その家は代々、何を仕事にしていた家？","a":"花火師です。"},{"tag":"ゆかり","hook":"ウルトラシリーズの生みの親の一人","t":"南風原町出身の脚本家、金城哲夫は第一期ウルトラシリーズを企画し、シリーズの基礎を作り上げた一人です。"},{"tag":"へえ","hook":"チブル星人は沖縄の言葉から","t":"ウルトラシリーズのチブル星人は沖縄の言葉で頭、ジラースは次郎叔父さんの意味で、沖縄を思わせる名前です。"},{"tag":"味","hook":"カボチャがモチーフのヒーロー","t":"南風原の太陽と土の恵みを受けた完熟カボチャをモチーフに、黄金戦隊かぼっちゃマンが地産地消や食育のために活動しました。"},{"tag":"歴史","hook":"戦後の沖縄を伝える文書館","t":"沖縄県公文書館は、県の公文書だけでなく琉球政府や琉球列島米国民政府の文書も扱う、戦後の沖縄を知るうえで貴重な施設です。"},{"tag":"車窓","hook":"那覇の外でも那覇市内料金","t":"南風原町の新川地区には那覇市内線のバスも乗り入れていて、那覇市外でも運賃は那覇市内均一の扱いです。"}]},"名護市":{"pref":"沖縄県","cards":[{"tag":"へえ","hook":"亜熱帯の町に雪が降った夜","t":"2016年1月24日の夜、名護で15分間みぞれが観測されました。沖縄本島で観測史上初めての雪でした。","teaser":true},{"tag":"数字","hook":"本島で面積1位","t":"面積は約210.4km²で、本島26市町村中1位の広さ。人口は約63,060人（2021年）です。"},{"tag":"へえ","hook":"名前の由来は目隠しの塀","t":"名護の大ガジュマルの名は、樹の下の石碑の別名ヒンプンシーから。ひんぷんとは、沖縄の家で門と母屋の間に立つ目隠しの塀のことです。"},{"tag":"歴史","hook":"マツを抱き込んだガジュマル","t":"ひんぷんガジュマルは、隣のリュウキュウマツの大木を抱き込みながら育ちました。1695年頃にはもう有名で、やがてマツは枯れたそうです。"},{"tag":"車窓","hook":"桜の名所はグスクの跡","t":"名護城はなんぐすくと読みます。城跡一帯は名護中央公園になっていて、名護城公園として日本さくら名所100選に選ばれています。"},{"tag":"味","hook":"ソーキそば発祥の地とも","t":"名護には数多くのソーキそばの名店が集まり、ソーキそばが生まれた地とも言われています。"},{"tag":"ゆかり","hook":"あのビール会社は名護生まれ","t":"オリオンビールは1957年、名護町で、沖縄ビール株式会社として設立されました。"},{"tag":"車窓","hook":"県内最初の海中公園","t":"東シナ海に突き出た部瀬名岬には、本土復帰前の1970年に県内最初の海中公園、ブセナ海中公園が設けられました。"},{"tag":"へえ","hook":"10mを超えるマングローブ","t":"屋我地島の饒平名の干潟には、高さ10メートルを超えるオヒルギというマングローブが育っています。"},{"tag":"歴史","hook":"橋の前は定期船で島へ","t":"屋我地島へは、1953年に初代の屋我地大橋ができるまで運天港からの定期船で渡りました。その初代の橋は1960年のチリ地震津波で上部が流されました。"},{"tag":"へえ","hook":"沖縄で最後に電気が来た集落","t":"名護市源河のオーシッタイ地区に電気が通ったことで、沖縄県で人が住むすべての地域に電気が行き渡りました。"},{"tag":"車窓","hook":"東の海にも西の海にも面する","t":"沖縄本島では、北端の国頭村と南端の糸満市を除くと、西と東の両方に海岸線をもつのは名護市だけです。"},{"tag":"ゆかり","hook":"名護の総地頭の本が寺子屋へ","t":"66歳で名護間切の総地頭となった程順則。中国の福州で刊行した六諭衍義は、のちに日本各地の寺子屋に広まりました。"},{"tag":"クイズ","q":"名護市の「名護の日」は何月何日？","a":"7月5日。「な（7）ご（5）」の語呂合わせです。"}]},"嘉手納町":{"pref":"沖縄県","cards":[{"tag":"ゆかり","hook":"サツマイモ伝来の地","t":"1605年、野国総管は中国の福州から鉢植えのサツマイモの苗を持ち帰り、野国村で試作しました。天候に強い芋は村に広まり、凶作から人々を救いました。","teaser":true},{"tag":"数字","hook":"約15.1km²に約13,301人が暮らす町","t":"面積は約15.1km²、人口は約13,301人（2021年）。1km²あたり約880人です。"},{"tag":"ゆかり","hook":"「芋大主」と呼ばれた人","t":"野国総管は、芋大主、ウムウフシュと呼ばれて親しまれています。嘉手納町では毎年秋に、野國總管まつりが開かれます。"},{"tag":"クイズ","q":"嘉手納町が2005年に宣言した、サツマイモの呼び名は？","a":"野国いも"},{"tag":"クイズ","q":"「嘉手納」を沖縄の言葉で言うと？","a":"かでぃなー"},{"tag":"歴史","hook":"山原船でにぎわった川の港","t":"戦前、比謝川の河口の港は山原船が運ぶ物資の集積地で、嘉手納は中部の交通の要所として栄えました。"},{"tag":"歴史","hook":"沖縄本島で最北の駅があった","t":"戦前の嘉手納駅は嘉手納線の終着駅で、沖縄本島の鉄道では最北の駅でした。北部へ向かう中継地として、人も荷物も多く集まりました。"},{"tag":"へえ","hook":"嘉手納線の前に総延長80km","t":"嘉手納線が開通する6年前の1917年には、台車の数が1000台を超え、軌道の総延長は80キロに達していました。"},{"tag":"車窓","hook":"「日本一」ともいわれたロータリー","t":"嘉手納ロータリーは、日本一ともいわれた大きなロータリー交差点でした。渋滞や事故が問題となり、2007年度に廃止されました。"},{"tag":"へえ","hook":"大蛇が住むと伝わる沼","t":"比謝川の屋良ムルチは、大雨のとき流れが渦を巻くため、深さ15メートルの淵ができた沼です。大蛇が住むという伝説が残ります。"},{"tag":"車窓","hook":"沖縄八景に数えられた石橋","t":"比謝川の比謝橋は、1866年頃に5つのアーチが連なる石橋となり、渓谷とともに沖縄八景の一つに数えられました。"},{"tag":"歴史","hook":"沖縄最古の土器文化が眠る","t":"町内の野国貝塚では、沖縄で最古の土器文化が確認されています。屋良城跡からは、謎の遺物といわれる線刻石版も見つかりました。"},{"tag":"へえ","hook":"中頭郡で初の「町」","t":"嘉手納村は1976年1月1日に町制を施行し、中頭郡では初の町となりました。"},{"tag":"車窓","hook":"かつて日本最南端の道の駅","t":"道の駅かでなは、2008年に道の駅豊崎がオープンするまで、日本最南端の道の駅でした。"}]},"国頭村":{"pref":"沖縄県","cards":[{"tag":"へえ","hook":"沖縄なのに最高気温8.4度","t":"1981年2月26日に観測された最高気温8.4度は、沖縄県内の観測史上、最も低い最高気温です。","teaser":true},{"tag":"数字","hook":"本島で面積2位","t":"面積は約194.8km²で、本島26市町村中2位の広さ。人口は約4,517人（2021年）です。"},{"tag":"車窓","hook":"岬から鹿児島県の島が見える","t":"沖縄本島最北端の辺戸岬と鹿児島県の与論島は近く、晴れた日には岬から与論島が見えます。"},{"tag":"へえ","hook":"海の底にある鍾乳洞","t":"茅打バンタの北にある辺戸岬ドームは、世界的にも珍しい海底の鍾乳洞で、ダイビングスポットとして知られています。"},{"tag":"車窓","hook":"茅の束がバラバラになる崖","t":"宜名真の茅打バンタは高さ約100メートルの断崖です。束ねた茅を投げ落とすと強風でバラバラになったのが名の由来といわれます。"},{"tag":"歴史","hook":"すれ違えず引き返した道","t":"昔は岩の裂け目の杭や木の根を頼りに崖を越えました。人と出くわすと一人が戻って道を譲ったので、戻る道とも呼ばれたそうです。"},{"tag":"へえ","hook":"世界最北端とされる熱帯カルスト","t":"大石林山は、2億5千万年前の石灰岩が雨などで削られ、とがった奇岩が並ぶ中国の石林のような景色です。熱帯カルストでは世界最北端とされます。"},{"tag":"クイズ","q":"琉球神話でアマミキヨが最初に降り立ったとされる、国頭村の森の名前は？","a":"安須森（アスムイ）"},{"tag":"へえ","hook":"最高峰は長く見過ごされた","t":"1916年の測量まで、沖縄本島の最高峰は本部半島の嘉津宇岳だと思われていました。与那覇岳は高原のような山で、集落から見えにくいためといわれます。"},{"tag":"ゆかり","hook":"ヤンバルクイナの発見は1981年","t":"1981年に与那覇岳のふもとで捕まえた鳥が新種と分かり、翌1982年にヤンバルクイナと名付けられました。"},{"tag":"歴史","hook":"ペリー艦隊のボートが寄った島","t":"安田ヶ島は、バジル・ホールやペリーの本でシドマスと記されました。1853年のペリー来航の際には艦載艇が寄港しています。"},{"tag":"歴史","hook":"沖縄最古級の、底がとがった土器","t":"宇佐浜遺跡で見つかった宇佐浜式土器は、沖縄で出土する尖底土器のなかで最古の部類と考えられています。"},{"tag":"味","hook":"お茶の名前はおくみどり","t":"村の北部にある奥地区は、おくみどりというお茶の産地です。また村には、共同店のある集落が多くあります。"},{"tag":"車窓","hook":"国道58号はここから始まる","t":"国道58号の沖縄県内の起点は国頭村の奥にあり、村営バスはこの起点にある奥バス停を終点にしています。"}]},"大宜味村":{"pref":"沖縄県","cards":[{"tag":"味","hook":"沖縄そばじゃない新そば","t":"村では本土と同じ和そばが栽培され、日本一早い新そばとうたわれています。村内のそば店で味わえます。","teaser":true},{"tag":"数字","hook":"人より自然が多い町","t":"1km²あたり約46人。本島で下から3番目の人口密度です。"},{"tag":"クイズ","q":"「長寿の里」とされる大宜味村が、村として掲げている宣言は？","a":"長寿日本一宣言"},{"tag":"ゆかり","hook":"織り手が人間国宝に","t":"喜如嘉の芭蕉布は1974年に重要無形文化財となり、2000年には織り手の平良敏子さんが人間国宝に認定されました。"},{"tag":"へえ","hook":"布になるまで23の工程","t":"芭蕉布は、バショウの繊維を木灰汁で煮て竹ばさみでしごき、染めるなど、23もの工程を経てようやく完成します。"},{"tag":"歴史","hook":"400年から500年続くとされる祭り","t":"塩屋のウンガミは、旧暦7月の盆明けの亥の日に、ノロの神事などで豊作豊漁を願う海神祭です。国の重要無形民俗文化財です。"},{"tag":"へえ","hook":"水に浸かって舟を迎える女たち","t":"祭りのハーリーでは、屋古、田港、塩屋の男たちの舟3隻が塩屋の浜を目指し、女たちが水に浸かって太鼓や手拍子で迎えます。"},{"tag":"車窓","hook":"板を敷き詰めたような海岸","t":"喜如嘉の板敷海岸では、砂浜に沿って1キロにわたり板状の岩が何枚も重なり、まるで板を敷いたように見えます。"},{"tag":"車窓","hook":"田んぼが紫のじゅうたんに","t":"喜如嘉のオクラレルカ水田は4月上旬から中旬が見頃です。鮮やかな紫の花が一面を覆い、紫のじゅうたんのようになります。"},{"tag":"歴史","hook":"県内唯一の大正のコンクリート建築","t":"大宜味村役場の旧庁舎は、大正時代のコンクリート建築として県内に残る唯一のもので、貴重な建物とされています。"},{"tag":"歴史","hook":"釘や木玉まで出てきたグスク","t":"根謝銘城跡には神アサギと御嶽があり、土器や青磁器から釘や木玉まで出土しています。城壁や遠見台の跡も残ります。"},{"tag":"車窓","hook":"橋ができて約8キロ近道に","t":"1963年に初代の塩屋大橋が開通し、宮城島を通って塩屋湾を回り込まずに行けるようになり、距離が約8キロ縮まりました。"},{"tag":"味","hook":"赤い土で育つ大根","t":"沖縄北部特有の酸性の赤土で育てる赤土大根は村の名産品です。道の駅おおぎみなどで手に入ります。"},{"tag":"車窓","hook":"川を歩いてたどり着く滝","t":"平南川の上流にあるター滝は、亜熱帯の森の中で清流を歩くリバートレッキングが楽しめ、夏は滝つぼで泳ぐこともできます。"}]},"宜野座村":{"pref":"沖縄県","cards":[{"tag":"へえ","hook":"沖縄の茶業の始まりは湖の底？","t":"かんな湖のほとりに、沖縄の茶業発祥地の碑があります。1627年に金武王子朝貞が薩摩から茶の種を持ち帰り、いまは湖底の茶敷に植えたとされます。","teaser":true},{"tag":"数字","hook":"約31.3km²に約5,900人が暮らす町","t":"面積は約31.3km²、人口は約5,900人（2021年）。1km²あたり約188人です。"},{"tag":"ゆかり","hook":"阪神タイガースのキャンプ地","t":"太平洋に面した宜野座村は、プロ野球、阪神タイガース一軍のキャンプ地になっています。"},{"tag":"へえ","hook":"沖縄の言葉では「じぬじゃ」","t":"宜野座は、国頭の言葉ではじぬざ、沖縄の言葉ではじぬじゃと呼ばれます。"},{"tag":"歴史","hook":"琉球王朝の頃は「上四ケ」","t":"1649年の絵図郷村帳には、古知屋、宜野座、惣慶、漢那の4つの村が見え、金武の間切のうちの上四ケとも呼ばれました。"},{"tag":"歴史","hook":"約10万人が身を寄せた地","t":"1945年の沖縄戦のころ、この地には民間人の収容所がいくつも連なり、多いときには約10万3千人が暮らしていました。"},{"tag":"へえ","hook":"湖の底には昔の田んぼ","t":"かんな湖の湖底は福地原と呼ばれ、17世紀より前に水田が拓かれたと考えられています。沖縄戦の直後まで苗代に使われていました。"},{"tag":"へえ","hook":"エビとカニのための魚道","t":"漢那ダムには、エビやカニ、ハゼがのぼるための小さな魚道が日本で初めて設けられました。幅は20センチほどです。"},{"tag":"車窓","hook":"明治のダムがお手本","t":"漢那ダムの本ダムは明治時代のダムの外観を参考に、石積み風の壁やガス灯風の照明で飾られています。"},{"tag":"車窓","hook":"高速道路から見るダム","t":"漢那ダムの脇ダムは沖縄自動車道と平行に置かれ、高速道路を走る車からの眺めにも配慮して造られています。"},{"tag":"へえ","hook":"小学生が植えたマングローブ","t":"漢那ダムの下流では、1990年12月に地元の小学生らが、メヒルギやオヒルギなど合わせて6,200本のマングローブを植えました。"},{"tag":"クイズ","q":"宜野座村は1946年、どの村から分かれて誕生した？","a":"当時の金武村、いまの金武町です。"},{"tag":"クイズ","q":"宜野座村の松田地区。1946年に改称する前の名前は？","a":"古知屋です。"}]},"宜野湾市":{"pref":"沖縄県","cards":[{"tag":"へえ","hook":"鉄道駅がひとつもない市","t":"市内には鉄道が通っていません。鉄道駅のない市としては、人口密度が全国で最も高いとされます。","teaser":true},{"tag":"数字","hook":"ぎゅっと人が集まる町","t":"1km²あたり約5,013人。本島26市町村中3位の人口密度です。"},{"tag":"へえ","hook":"沖縄の言葉では「じのーん」","t":"宜野湾は、沖縄の言葉ではじのーんと呼ばれます。沖縄本島中南部の、ちょうど真ん中に位置する市です。"},{"tag":"へえ","hook":"「ねたて」ってどういう意味？","t":"市のキャッチフレーズは、ねたての都市ぎのわん。ねたてはおもろさうしにも出てくる言葉で、物事の根元や共同体の中心を意味します。"},{"tag":"歴史","hook":"戦前は「ケービン」が走った","t":"戦前は軽便鉄道の嘉手納線が通っていて、通称はケービン。市内には大謝名駅、真志喜停車場、大山駅がありました。"},{"tag":"車窓","hook":"約4kmに30余りの車屋さん","t":"国道330号の志真志から野嵩までの約4キロに、30余りの自動車販売店が並びます。ほとんどが中古車店で、宜野湾中古車街道とも呼ばれます。"},{"tag":"車窓","hook":"湧き水で育つタイモ畑","t":"大山地域は湧き水が豊富で、タイモの栽培が盛んです。国道58号と宜野湾バイパスの間に、タイモ畑が広がっています。"},{"tag":"へえ","hook":"神社の裏に長さ280mの鍾乳洞","t":"普天満宮の社殿裏には、全長280メートルの鍾乳洞があります。2万年前の動物の化石なども見つかり、一部は無料で公開されています。"},{"tag":"歴史","hook":"王様が毎年お参りした神社","t":"1644年に尚賢王が普天満宮へ参詣して以来、毎年9月に国王一行が無病息災を祈ってお参りするようになりました。"},{"tag":"歴史","hook":"5kmの松並木「じのーんなんまち」","t":"普天満宮から首里への参詣道には、リュウキュウマツの並木が5キロにわたって続き、国の天然記念物でした。沖縄戦の頃にほとんどが失われました。"},{"tag":"ゆかり","hook":"天女と出会った泉の伝説","t":"真志喜の湧き水、森の川には伝説があります。察度王は、ここで出会った奥間大親と天女の間に生まれたと伝わっています。"},{"tag":"へえ","hook":"4月に「日本で一番早い夏」","t":"毎年4月、宜野湾海浜公園で花火大会の琉球海炎祭が開かれます。日本で一番早い夏をうたい、沖縄の海開きに合わせた催しです。"},{"tag":"ゆかり","hook":"慰霊の日の夕日に向く階段","t":"佐喜眞美術館の屋上の階段は、慰霊の日である6月23日に太陽が沈む線に合わせて設計されています。"},{"tag":"クイズ","q":"森の川（ムイヌカー）の「カー」は、川ではなく何のこと？","a":"泉"}]},"恩納村":{"pref":"沖縄県","cards":[{"tag":"歴史","hook":"名付け親は琉球の王さま","t":"万座毛の名は、1726年に訪れた尚敬王が、その絶景を万人を座しめるに足る毛、とたたえたことから付いたと言われています。","teaser":true},{"tag":"数字","hook":"約50.8km²に約10,852人が暮らす町","t":"面積は約50.8km²、人口は約10,852人（2021年）。1km²あたり約213人です。"},{"tag":"車窓","hook":"崖に象の鼻そっくりの岩","t":"万座毛は高さ約20メートルの琉球石灰岩の絶壁で、象の鼻に似た奇岩があり、崖の上は芝生の台地になっています。"},{"tag":"ゆかり","hook":"怪獣が眠っていた岬","t":"映画ゴジラ対メカゴジラでは、怪獣キングシーサーが万座毛に眠っていたことになっています。"},{"tag":"ゆかり","hook":"禁止の立て札を詠んだ歌","t":"役人が若者の毛遊びを禁じる立て札を立てたとき、恩納なべが詠んだ歌は、皮肉にも王府で舞われる恩納節の歌詞になりました。"},{"tag":"へえ","hook":"青の洞窟は昔の避難所","t":"青の洞窟は地元でクマヤーガマと呼ばれ、かつては台風のときなどに、漁師が船を避難させる場所でした。"},{"tag":"へえ","hook":"レジャーでは入れない海底鍾乳洞","t":"恩納村の広部ガマは、日本一の海底鍾乳洞と紹介されています。ただし、レジャーダイビングでは入ることができません。"},{"tag":"へえ","hook":"ことばの境目が村の中に","t":"沖縄北部の方言と中南部の方言の境目は、本島の西海岸では、恩納村の恩納と谷茶の間にあるといわれています。"},{"tag":"へえ","hook":"首里から一番近いやんばる","t":"恩納村は、首里や那覇から見てやんばるで最も近い所にあるため、近山原とも呼ばれていました。"},{"tag":"味","hook":"森のアイスクリームの里","t":"森のアイスクリームとも呼ばれる果物アテモヤ。恩納村は、作付け面積、生産量ともに沖縄県内で1位とされています。"},{"tag":"へえ","hook":"村ぐるみでサンゴを守る","t":"恩納村では1989年から漁協がサンゴの移植活動を続け、2018年には、サンゴの村を宣言しました。"},{"tag":"へえ","hook":"トイレと豚小屋が一体に","t":"琉球村に移された旧平田家住宅のフールは、便所と豚の飼育場を兼ねた沖縄特有の建物で、登録有形文化財です。"},{"tag":"ゆかり","hook":"ノーベル賞受賞者が教授を務めた大学","t":"2022年、恩納村の沖縄科学技術大学院大学で兼任の教授を務めるスバンテ・ペーボが、ノーベル生理学・医学賞を受賞しました。"},{"tag":"クイズ","q":"恩納村の「恩納」、沖縄の言葉では何と読む？","a":"うんな"}]},"本部町":{"pref":"沖縄県","cards":[{"tag":"へえ","hook":"しょっぱい水が流れる川","t":"本部町の塩川は、国内で唯一の塩分濃度の高い川です。沖縄返還の当日に、国の天然記念物に指定されました。","teaser":true},{"tag":"数字","hook":"約54.4km²に約13,073人が暮らす町","t":"面積は約54.4km²、人口は約13,073人（2021年）。1km²あたり約241人です。"},{"tag":"へえ","hook":"満ち潮で増えるとされた湧き水","t":"塩川の湧き水の量は那覇港の潮位と連動していて、満潮のときに増え、干潮のときに減るとされてきました。"},{"tag":"車窓","hook":"日本で最も早い花見で知られる山","t":"八重岳の道路沿いには約7千本のカンヒザクラが植えられ、1月下旬に咲くことから、日本で最も早く桜が見られることで知られています。"},{"tag":"歴史","hook":"桜の山に刻まれた記憶","t":"八重岳は沖縄戦のとき、本島北部で唯一、日米両軍が向かい合って戦った場所です。"},{"tag":"へえ","hook":"ジンベエザメ飼育の世界初","t":"沖縄美ら海水族館は、ジンベエザメやナンヨウマンタの長期飼育に世界で初めて成功しました。ジンベエザメは館のキャラクターにもなっています。"},{"tag":"へえ","hook":"大水槽が深さ10mのわけ","t":"エサを食べるとき体を縦にするジンベエザメの尾が、水底をこすらないように、大水槽の深さは10メートルにされました。"},{"tag":"クイズ","q":"「美ら海（ちゅらうみ）」は沖縄の方言でどんな意味？","a":"清らしい海"},{"tag":"へえ","hook":"県内一の花火大会","t":"海洋博公園で毎年7月に開かれるサマーフェスティバルの花火大会は、沖縄県内一の規模で行われています。"},{"tag":"へえ","hook":"上から見るとクロワッサン","t":"本部半島の沖に浮かぶ水納島は三日月型の小さな島で、空から見るとクロワッサンに見えるため、クロワッサンアイランドと呼ばれています。"},{"tag":"車窓","hook":"完成当時は沖縄最長の橋","t":"瀬底島へ渡る瀬底大橋は1985年に完成した全長762メートルの橋で、当時は沖縄県で最長の橋でした。"},{"tag":"へえ","hook":"ヤギどうしが闘う島の行事","t":"瀬底島では毎年5月と11月に、ピージャーオーラサイと呼ばれる、ヤギどうしを闘わせる伝統行事が行われます。"},{"tag":"ゆかり","hook":"国会議事堂に瀬底の石","t":"瀬底島では昭和の初めにトラバーチンという石灰質の岩石が採れ、国会議事堂の建材にも使われました。"},{"tag":"車窓","hook":"ゴリラがチョップする岩","t":"本部町には、ゴリラがチョップしているような形の奇岩、ゴリラチョップがあります。周りはシュノーケリングのポイントです。"}]},"東村":{"pref":"沖縄県","cards":[{"tag":"へえ","hook":"本島で唯一、路線バスがない","t":"2018年に路線バスが廃止され、東村は沖縄本島の市町村で唯一、民間の路線バスが走っていません。代わりに運賃無料のコミュニティバスが走ります。","teaser":true},{"tag":"数字","hook":"本島で面積4位","t":"面積は約81.9km²で、本島26市町村中4位の広さ。人口は約1,565人（2021年）です。"},{"tag":"へえ","hook":"日の出るところ、東なり","t":"東村の名前は、太平洋に面して朝日が昇ることから、日の出るところ東なり、として名付けられました。"},{"tag":"車窓","hook":"本島で2番目に広いマングローブ","t":"慶佐次川の河口には長さ約1キロにわたってヒルギ林が広がり、沖縄本島のマングローブとして2番目の広さがあります。"},{"tag":"へえ","hook":"シオマネキが暮らす森","t":"慶佐次湾のマングローブでは、ハクセンシオマネキなどのカニやミナミトビハゼ、シギやカワセミなどの鳥が見られます。"},{"tag":"歴史","hook":"アメリカが着工し日本が完成","t":"沖縄県最大の福地ダムは、琉球列島米国民政府のもとで着工され、建設途中で日本政府に引き継がれて1974年に完成しました。"},{"tag":"へえ","hook":"湖の水を直接太平洋へ","t":"福地ダムは洪水の時、湖の東端から水を直接太平洋へ流します。そのサイフォン式の洪水吐きは日本最大の規模です。"},{"tag":"ゆかり","hook":"ダムのマスコットはパイナップル","t":"福地ダムのマスコットキャラクターは、カヌーを操るパイナップルをモチーフにしたパヌーです。"},{"tag":"へえ","hook":"犬をのみ込んだ大ウナギ","t":"福地川には大ウナギがすんでいたという記録があり、大ウナギに犬がのみ込まれたという言い伝えも残っています。"},{"tag":"車窓","hook":"本島一周道路は1981年に完成","t":"1981年、東村高江と国頭村安波の間がつながり、沖縄本島をぐるりと回る一周道路が完成しました。"},{"tag":"ゆかり","hook":"国立公園の誕生日は虫の発見日","t":"やんばる国立公園の指定日は、地元の要望で、ヤンバルテナガコガネが発見された1983年9月15日にちなんで決められました。"},{"tag":"へえ","hook":"自然体験の旅の草分け","t":"東村は、エコツーリズムやブルーツーリズムといった自然体験型の観光で、沖縄県内の草分け的な地域です。"},{"tag":"クイズ","q":"東村の「村の花」とされている花は？","a":"ツツジ"},{"tag":"ゆかり","hook":"宮里きょうだいのふるさと","t":"プロゴルファーの宮里藍さん、宮里聖志さん、宮里優作さんのきょうだいは東村の出身です。"}]},"沖縄市":{"pref":"沖縄県","cards":[{"tag":"へえ","hook":"鉄道のない市で日本一","t":"沖縄県で2番目に人口が多い沖縄市は、鉄道のない市としては日本一人口の多い市でもあります。","teaser":true},{"tag":"数字","hook":"本島で人口2位","t":"人口は約142,094人（2021年）で、本島26市町村中2位。面積は約49.7km²です。"},{"tag":"歴史","hook":"「うるま市」という案も届いた","t":"沖縄市の名前は公募で選ばれました。案の中には、のちに近くで誕生する「うるま市」という名前も寄せられていました。"},{"tag":"ゆかり","hook":"コザの名は米軍の呼び名から","t":"旧コザ市の名前は、米軍が越来村の胡屋地区をKOZAと呼び、人々もそう呼ぶようになったのが始まりとされます。諸説あります。"},{"tag":"へえ","hook":"「エイサーのまち」を宣言","t":"沖縄市は県内で最もエイサーが盛んな地域で、2007年には「エイサーのまち」を宣言しました。"},{"tag":"へえ","hook":"夏の週末はエイサーナイト","t":"6月から全島エイサーまつりの本祭までの間、市内の数か所で毎週末、エイサーナイトというイベントが開かれます。"},{"tag":"歴史","hook":"7月4日に開業した老舗","t":"プラザハウスは1954年7月4日に開業し、日本で最古のショッピングセンターとされています。"},{"tag":"歴史","hook":"のちの国王が暮らした城","t":"越来城に入った尚泰久は越来王子と呼ばれ、のちに琉球国王となって首里城へ移りました。"},{"tag":"車窓","hook":"看板に英語が並ぶ通り","t":"胡屋十字路から嘉手納基地のゲートへ続くコザゲート通りは、米軍人が多く訪れ、日本語と英語を並べた看板の店が多い通りです。"},{"tag":"へえ","hook":"渡り鳥ムナグロの冬の宿","t":"泡瀬干潟は、チドリの仲間のムナグロという渡り鳥の越冬地として日本最大です。"},{"tag":"歴史","hook":"那覇を抜いた泡瀬の塩","t":"泡瀬の製塩量は那覇を抜き、県内でも随一の規模になりました。"},{"tag":"歴史","hook":"沖縄戦の降伏調印の地","t":"1945年9月7日、越来村の森根で、米軍と日本軍の代表による降伏の調印が行われました。"},{"tag":"へえ","hook":"南国の植物が5万株以上","t":"知花にある東南植物楽園は、約1,300種5万株以上の植物がそろう、日本最大級の屋外植物園です。"},{"tag":"クイズ","q":"泡瀬地区は18世紀まで、何と呼ばれる砂州の無人島だったと考えられている？","a":"あせ嶋"}]},"浦添市":{"pref":"沖縄県","cards":[{"tag":"へえ","hook":"王の父は太陽？「てだこの街」","t":"浦添で栄えた英祖王の父は、太陽だったという伝説が伝わっています。そこから浦添は、太陽の子を意味する「てだこの街」とも呼ばれます。","teaser":true},{"tag":"数字","hook":"本島で人口4位","t":"人口は約115,855人（2021年）で、本島26市町村中4位。面積は約19.5km²です。"},{"tag":"歴史","hook":"約220年続いた琉球の古都","t":"浦添は12世紀から14世紀の約220年間、浦添城を中心に琉球王国の首都として栄えました。"},{"tag":"歴史","hook":"浦添の名は「ウラオソイ」から？","t":"浦添の名は、津々浦々を支配するという意味の「ウラオソイ」が由来とされます。それがウラシイに変わり、浦添の字が当てられました。"},{"tag":"へえ","hook":"牧港は「待つ港」だった？","t":"源為朝の妻子が夫の帰りを待ち続けた待港が、牧港に変わったという伝説が伝わっています。ただし民間語源だとする見方もあります。"},{"tag":"歴史","hook":"王の墓「ようどれ」は夕凪の意味","t":"浦添城跡の崖の中腹にある王の墓、浦添ようどれ。ようどれとは夕凪のことで、極楽陵という別名もあります。"},{"tag":"車窓","hook":"城跡にそびえる巨岩ワカリジー","t":"浦添城跡の東端には、ワカリジーと呼ばれる巨大な岩があります。頂上は標高約148メートルで、浦添市内の最高地点です。"},{"tag":"歴史","hook":"映画「ハクソー・リッジ」の崖","t":"浦添城跡の南東の崖は、沖縄戦で激しい攻防が続いた前田高地です。負傷兵を救った衛生兵の姿は、2016年の映画「ハクソー・リッジ」で描かれました。"},{"tag":"へえ","hook":"日本初の漆芸専門美術館","t":"浦添市美術館は1990年に設立された、日本初の漆芸専門の美術館です。沖縄初の公立美術館でもあり、琉球漆器を収蔵しています。"},{"tag":"ゆかり","hook":"全国で5番目の国立劇場","t":"2004年に開場した国立劇場おきなわは、全国で5番目の国立劇場です。沖縄の伝統芸能を守り伝えるために造られました。"},{"tag":"車窓","hook":"2005年、交通量トップ3を独占","t":"2005年の九州・沖縄の一般道路の交通量では、上位3位を浦添市が占めました。1位は牧港一丁目でした。"},{"tag":"車窓","hook":"今も残る軽便鉄道の線路","t":"浦添にはかつて、ケービンと呼ばれた沖縄県営鉄道嘉手納線が走り、牧港駅・城間駅・内間駅がありました。大平特別支援学校前バス停の近くに、線路の一部が残っています。"},{"tag":"歴史","hook":"市民がつくる、てだこまつり","t":"浦添てだこまつりは1978年に始まりました。合言葉は「市民自らによる市民のまつりを」です。"},{"tag":"クイズ","q":"浦添市が2004年に宣言した「○○王国都市宣言」。○○に入るスポーツは？","a":"ハンドボール（市内の全公立小中学校にハンドボール部があります）"}]},"糸満市":{"pref":"沖縄県","cards":[{"tag":"へえ","hook":"本当の最南端は喜屋武岬じゃない","t":"沖縄本島の最南端と誤解されがちな喜屋武岬ですが、実際の最南端は東南東へ約1.4キロ離れた荒崎です。","teaser":true},{"tag":"数字","hook":"約46.6km²に約60,903人が暮らす町","t":"面積は約46.6km²、人口は約60,903人（2021年）。1km²あたり約1,306人です。"},{"tag":"へえ","hook":"二つの海の境目になる岬","t":"荒崎と宮古島の東平安名崎を結ぶ線は、東シナ海と太平洋の境界線として定義されています。"},{"tag":"へえ","hook":"キャンは「〜まで」の意味？","t":"喜屋武は沖縄の言葉でキャン。限度や到達を表す「〜まで」の意味の、きやめから変化したと考えられています。"},{"tag":"へえ","hook":"ハーリーではなくハーレー","t":"県内では一般にハーリーと呼ぶ舟漕ぎ行事を、伝統を重んじる糸満では、本来の名称のハーレーと呼んでいます。"},{"tag":"へえ","hook":"わざと舟をひっくり返すレース","t":"糸満ハーレーには、途中で一斉に舟を転覆させ、泳ぎながら元に戻して再び乗り込む、糸満独自の競漕があります。"},{"tag":"クイズ","q":"糸満ハーレーの神事性を重んじる競漕。勝った舟から順にお参りし、大漁と航海安全を祈る場所は？","a":"白銀堂です。"},{"tag":"歴史","hook":"南山最後の王が最期を迎えた丘","t":"糸満ロータリーの近くにある丘、山巓毛は、1429年に南山最後の王が中山の尚巴志の攻撃を受け、最期を迎えた場所です。"},{"tag":"歴史","hook":"小学校の中に残るグスク跡","t":"三山時代のグスク跡、南山城跡は、高嶺小学校の敷地内に城壁と遺構が残っています。"},{"tag":"歴史","hook":"久米島と同じ名前の城","t":"具志川城跡は、久米島の具志川城の城主が攻められてこの地へ逃れ、同じ名の城を築いたと伝えられています。"},{"tag":"へえ","hook":"米軍の空き瓶から生まれたガラス","t":"琉球ガラスは戦後の資源難の中、アメリカ軍基地で捨てられたコーラやビールの空き瓶を溶かして再利用したのが始まりです。"},{"tag":"ゆかり","hook":"くり舟で南洋へ出た漁師たち","t":"糸満の漁民はサバニと呼ばれるくり舟で南洋各地へ出漁し、男性は追込漁、女性は魚の行商をしていました。"},{"tag":"へえ","hook":"地名は「優れた漁師」の意味？","t":"糸満の地名の由来には諸説あり、優れたを意味するイトと、海人のアマを合わせて優れた漁師、とする説があります。"},{"tag":"歴史","hook":"平和への祈りが集まる南部","t":"市の南部、旧三和村一帯は沖縄戦の激戦地で、ひめゆりの塔などが建てられ、沖縄戦跡国定公園に指定されています。"}]},"西原町":{"pref":"沖縄県","cards":[{"tag":"へえ","hook":"西原なのに、由来は北","t":"沖縄の言葉で、にしは北のこと。西原の名は、琉球王国の中心だった首里の北にあることに由来します。","teaser":true},{"tag":"数字","hook":"約15.5km²に約34,802人が暮らす町","t":"面積は約15.5km²、人口は約34,802人（2021年）。1km²あたり約2,241人です。"},{"tag":"へえ","hook":"日本最南端の総合大学","t":"西原町に本部がある琉球大学は、沖縄県唯一の国立大学で、日本最南端かつ最西端の総合大学です。"},{"tag":"へえ","hook":"正門が3つある大学","t":"琉球大学の千原キャンパスは3つの市町村にまたがり、それぞれにある北口、南口、東口のすべてが正門とされています。"},{"tag":"クイズ","q":"3つの大学がある西原町。町は自らを何のまちとしている？","a":"文教のまちです。"},{"tag":"ゆかり","hook":"王になる前の金丸の旧宅跡","t":"内間御殿は、のちの尚円王である金丸が内間地頭だったころの旧宅跡に、1666年に創建された神殿です。"},{"tag":"歴史","hook":"王が自ら探した盗まれた枕","t":"1735年、内間御殿の御神体の宝枕が盗まれ、尚敬王が自ら家臣を連れて探し、田の中から見つけたといいます。"},{"tag":"ゆかり","hook":"図書館のマスコットはウンタマギルー","t":"西原町の町立図書館のマスコットキャラクターは、ウンタマギルー（運玉義留）です。"},{"tag":"へえ","hook":"全国でも珍しかったすぐやる課","t":"西原町には全国的にも珍しいすぐやる課が平成22年3月まで置かれ、その後すぐやる係に変わりました。"},{"tag":"車窓","hook":"床屋が多いサンパチ通り","t":"県道38号浦添西原線は、床屋が多いことから、サンパチ通りの愛称でも親しまれています。"},{"tag":"車窓","hook":"県内初、高速どうしのジャンクション","t":"2000年に新設された西原ジャンクションは、沖縄県内で初めての、高速道路どうしをつなぐジャンクションです。"},{"tag":"車窓","hook":"マリンパークの人工ビーチ","t":"西原マリンパークには、西原きらきらビーチという人工ビーチがあります。"},{"tag":"歴史","hook":"田んぼの町からサトウキビの町へ","t":"戦前は稲作が中心だった西原町は、戦後サトウキビの名産地となり、県中南部で最大規模の製糖工場もありました。"},{"tag":"歴史","hook":"サトウキビ用に計画された軌道","t":"沖縄軌道は、もとは今の西原町にあった製糖工場へサトウキビを運ぶトロッコとして計画されました。製糖期のほかは使い道がなく、旅客を運ぶ会社が別に作られました。"}]},"読谷村":{"pref":"沖縄県","cards":[{"tag":"歴史","hook":"沖縄の歴史を7000年前へ","t":"比謝川の河口近くの渡具知東原遺跡で爪形文土器が見つかり、沖縄の先史時代文化が約7000年前までさかのぼると分かりました。","teaser":true},{"tag":"数字","hook":"約35.3km²に約39,791人が暮らす町","t":"面積は約35.3km²、人口は約39,791人（2021年）。1km²あたり約1,128人です。"},{"tag":"へえ","hook":"昔の呼び名はゆんたんざ","t":"読谷は、もとは沖縄の言葉でこの地域をゆんたんざと呼び、読谷山という字を当てていました。"},{"tag":"歴史","hook":"築城の名人、護佐丸の城","t":"座喜味城は15世紀初頭、築城家として名高い読谷山按司の護佐丸が築いたといわれるグスクです。"},{"tag":"車窓","hook":"城跡から慶良間諸島まで","t":"座喜味城跡は2000年に世界遺産に登録されました。高台から西を望むと残波岬、晴れた日には慶良間諸島まで見えます。"},{"tag":"歴史","hook":"がれきの丘からよみがえった城","t":"座喜味城は十・十空襲と沖縄戦で壊滅的な被害を受け、米軍の通信基地にもなりました。1974年に返還され、復旧が進んで美しいグスクによみがえりました。"},{"tag":"車窓","hook":"てっぺんまで登れる灯台","t":"残波岬灯台は上まで登れる参観灯台です。晴れていれば、粟国島や渡名喜島、久米島などを見渡せます。"},{"tag":"車窓","hook":"断崖が約2キロ続く岬","t":"残波岬灯台の周りには、高さ30メートルから40メートルの断崖絶壁が約2キロも続く、雄大な景色が広がります。"},{"tag":"クイズ","q":"残波岬の古い呼び名「於仁志崎」の「にし」は、首里から見てどの方角？","a":"北。浦添や首里から見て、ずっと北の方の土地という意味からといわれます"},{"tag":"歴史","hook":"沖縄で初めて確認された石棺墓群","t":"木綿原遺跡は、沖縄で初めて確認された先史時代の石棺墓群で、1978年に国の史跡に指定されました。"},{"tag":"歴史","hook":"二つの上陸を見た浜","t":"渡具知ビーチ周辺は、琉球侵攻で薩摩軍が本格的に上陸したと伝わる浜で、1945年4月1日にはアメリカ軍の上陸地点にもなりました。"},{"tag":"ゆかり","hook":"大河ドラマのセットで体験","t":"むら咲むらは、大河ドラマ琉球の風の撮影に使われたオープンセットを利用した、体験型のテーマパークです。"},{"tag":"ゆかり","hook":"Kiroroのふたりの出身地","t":"歌手のKiroroのメンバー、玉城千春さんと金城綾乃さんは読谷村の出身です。"}]},"豊見城市":{"pref":"沖縄県","cards":[{"tag":"へえ","hook":"村なのに「役所」を名乗った","t":"市になる前の豊見城村の事務所は、日本の町村で唯一「役所」と名乗っていました。ふつうの町村なら「役場」です。","teaser":true},{"tag":"数字","hook":"約19.2km²に約64,850人が暮らす町","t":"面積は約19.2km²、人口は約64,850人（2021年）。1km²あたり約3,379人です。"},{"tag":"歴史","hook":"かつて人口日本一だった村","t":"豊見城は1976年に日本一人口の多い村になりましたが、その後ほかの村に抜かれ、2002年に単独で市になりました。村が市になった初めての例です。"},{"tag":"へえ","hook":"同じ豊見城でも読みが二つ","t":"豊見城中学校は、とみぐすくと読みます。一方、豊見城小学校や市内の県立高校は、とみしろと読みます。"},{"tag":"歴史","hook":"ハーリーは豊見城から始まった？","t":"歴史書の球陽によると、豊見城城主の汪応祖が中国で龍船の競漕に感激し、帰国後に船を造って遊覧したのがハーリーの始まりとされます。"},{"tag":"ゆかり","hook":"ジョン万次郎がつないだ縁","t":"1851年に琉球に上陸したジョン万次郎は、高安家で手厚くもてなされました。この縁で、豊見城市と土佐清水市は姉妹都市になっています。"},{"tag":"車窓","hook":"飛行機の離着陸が見える島","t":"瀬長島は海中道路で本島とつながり、車で渡れます。那覇空港の隣にあり、離着陸する飛行機を見物できるため、撮影に訪れる航空ファンもいます。"},{"tag":"歴史","hook":"女神が最初に降り立った島","t":"瀬長島は豊見城発祥の地とされます。琉球開闢の女神アマミキヨが、最初に降り立った島だと伝わっています。"},{"tag":"へえ","hook":"ニワトリが鳴かない島","t":"瀬長島では、ハブが鶏を捕まえて食べてしまうため、昔から鶏を飼いませんでした。そこで「鶏鳴かん島」とも呼ばれていました。"},{"tag":"歴史","hook":"よみがえった石のアーチ橋","t":"真玉橋は1708年に5連の石造アーチ橋になりました。沖縄戦で壊されましたが、2002年に再びアーチ橋として架けられました。"},{"tag":"車窓","hook":"日本最西端の道の駅","t":"豊見城市の道の駅豊崎は、日本最西端の道の駅です。沖縄本島南部で初の道の駅でもあります。"},{"tag":"車窓","hook":"沖縄のテレビ電波はここから","t":"沖縄県内のテレビ局すべての本送信所が、豊見城市内の3カ所に置かれています。"},{"tag":"クイズ","q":"豊見城市の地名「保栄茂」。何と読む？","a":"びん（しまくとぅばでもビン）"}]},"那覇市":{"pref":"沖縄県","cards":[{"tag":"へえ","hook":"中央分離帯が外せる国道","t":"大綱挽の日は、会場の交差点付近で中央分離帯のブロックが取り外されます。取り外せる場所は、全国の国道でここだけです。","teaser":true},{"tag":"数字","hook":"本島で人口1位","t":"人口は約316,048人（2021年）で、本島26市町村中1位。面積は約40.0km²です。"},{"tag":"へえ","hook":"ギネス認定、世界一の大綱","t":"那覇大綱挽まつりの主役は、全長200mの大綱です。ギネスブックに認定された世界一の綱挽で、スポーツの日を含む3連休に開かれます。"},{"tag":"歴史","hook":"戦後の焼け跡から奇跡の1マイル","t":"国際通りの名は、1948年に建てられたアーニーパイル国際劇場にちなみます。長さがほぼ1マイルで、奇跡の1マイルとも呼ばれます。"},{"tag":"へえ","hook":"石碑には「こくさいとおり」","t":"国際通りは一般に、こくさいどおりと呼ばれます。ところが通りの入り口には、こくさいとおりと彫られたシーサーの石碑があります。"},{"tag":"へえ","hook":"JRが通らない県庁所在地","t":"那覇市は、JR線も大手私鉄も通っていない、唯一の都道府県庁所在地です。"},{"tag":"歴史","hook":"那覇はもともと島だった","t":"那覇はかつて、河口の湾に散らばる島々でした。1451年、長さ1kmに及ぶ堤道「長虹堤」が築かれ、沖縄本島とつながりました。"},{"tag":"歴史","hook":"那覇の語源は「魚場」","t":"那覇という地名は、漁場を表す魚場と書いて、なはと読む言葉が語源です。民俗学者の伊波普猷が唱えた説として知られます。"},{"tag":"歴史","hook":"城跡が大学のキャンパスに","t":"戦後の首里城跡は、1950年から1982年まで琉球大学のキャンパスとして使われていました。"},{"tag":"へえ","hook":"わざと海が見えない展望台","t":"王家の庭園、識名園の展望台「勧耕台」からは海が見えません。琉球をより大きな国に見せるためともいわれています。"},{"tag":"ゆかり","hook":"「ちゅらさん」の家がある坂道","t":"首里金城町石畳道は日本の道100選の一つです。NHKドラマ「ちゅらさん」の撮影地で、沿道の民家が主人公の家として使われました。"},{"tag":"歴史","hook":"三つの窯を集めた焼き物の町","t":"尚貞王の時代の1682年、三カ所の窯を牧志村の南に集めて、新しい窯場ができました。これが壺屋焼の始まりです。"},{"tag":"ゆかり","hook":"高台の神社「なんみんさん」","t":"那覇港を望む高台に立つ波上宮は、なんみんさんと呼ばれ親しまれています。5月17日の例大祭に合わせた、なんみん祭は特ににぎわいます。"},{"tag":"クイズ","q":"2003年に那覇で開業した、戦後沖縄で初の営業用鉄道の愛称は？","a":"ゆいレール（沖縄都市モノレール線）"}]},"金武町":{"pref":"沖縄県","cards":[{"tag":"味","hook":"タコライスはこの町生まれ","t":"沖縄を代表するB級グルメのタコライスは、金武町の新開地のパーラー千里で生まれました。","teaser":true},{"tag":"数字","hook":"約37.8km²に約11,252人が暮らす町","t":"面積は約37.8km²、人口は約11,252人（2021年）。1km²あたり約297人です。"},{"tag":"味","hook":"安くて大盛りを求めて","t":"タコライスは1984年、パーラー千里の創業者が考えました。お金を切り詰める海兵隊員を見て、安くて量の多い食事をと、人気のタコスをご飯にのせたのが始まりです。"},{"tag":"味","hook":"豚の血で炒める郷土料理","t":"チーイリチャーは、豚肉に豚の血を混ぜて炒めた料理です。地域の行事やお祝いで食べられ、町内の食堂でも味わえます。"},{"tag":"味","hook":"田芋がスイーツと焼酎に","t":"特産の田芋は、パイやチーズケーキなどの田芋スイーツや、金武酒造の田芋焼酎にも姿を変えています。"},{"tag":"味","hook":"沖縄でウナギの養殖","t":"並里区の福花原にはウナギの養殖場があります。金武町産のウナギは蒲焼きとしてスーパーに並び、那覇の和食店でも出されています。"},{"tag":"歴史","hook":"沖縄初の海外移民の町","t":"1899年、當山久三の指導で沖縄初の海外移民が始まりました。金武間切の出身者を中心に26人がハワイへ渡りました。"},{"tag":"ゆかり","hook":"移民が贈った銅像","t":"當山久三の銅像は1931年、アメリカに渡った移民たちの寄付で建てられました。1944年に金属回収で撤去され、1961年に再建されています。"},{"tag":"歴史","hook":"空き缶の三線から生まれた歌","t":"1945年に屋嘉に置かれた捕虜収容所で、捕虜たちが空き缶や木材、パラシュートのひもでカンカラ三線を作って歌ったのが、民謡屋嘉節の始まりです。"},{"tag":"へえ","hook":"ペリーが泊まったオランダ森","t":"1853年、ペリー艦隊は並里集落の北の丘で宿営しました。当時は西洋人をみなウランダーと呼んだため、その森はオランダ森と呼ばれるようになりました。"},{"tag":"歴史","hook":"流れ着いた僧と鍾乳洞","t":"16世紀、日秀上人は遭難して金武に流れ着き、鍾乳洞を拠点に布教して観音寺を建てたと伝えられています。その洞窟は日秀洞と呼ばれています。"},{"tag":"車窓","hook":"戦前の姿を残す木造の寺","t":"戦争で多くの寺社が失われた沖縄で、金武観音寺は戦前の古い建築様式が残る、貴重な木造の建物です。"},{"tag":"へえ","hook":"十五夜の村あすび","t":"旧暦8月15日の夜、金武区、並里区、伊芸区で観月祭が開かれます。並里区では十五夜村あすびと呼ばれています。"},{"tag":"クイズ","q":"金武町の「金武」。沖縄の言葉では何と呼ぶ？","a":"「ちん」です。"}]}};
